package com.huiqiyikang.assessment.service;
import com.huiqiyikang.assessment.entity.*; import com.huiqiyikang.assessment.mapper.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class TaskService { final AssessmentTaskRepository tasks; final ClassRoomRepository classes; final ClassQuestionRepository questions; final ClassMemberRepository members; final TeacherRepository teachers;
 public TaskService(AssessmentTaskRepository t,ClassRoomRepository c,ClassQuestionRepository q,ClassMemberRepository m,TeacherRepository tr){tasks=t;classes=c;questions=q;members=m;teachers=tr;} public Optional<AssessmentTask> findById(Long id){return tasks.findById(id);} public AssessmentTask save(AssessmentTask x){return tasks.save(x);} public List<AssessmentTask> byClass(Long id){return tasks.findByClassIdAndStatus(id,"active");} public List<AssessmentTask> findByClassIdAndStatus(Long id,String status){return tasks.findByClassIdAndStatus(id,status);} public List<ClassQuestion> classQuestions(Long id){return questions.findByClassIdAndStatus(id,"active");} public int classQuestionCount(Long id){return questions.findByClassIdAndStatus(id,"active").size();} public List<ClassMember> members(Long id){return members.findByStudentUserIdAndStatus(id,"active");} public Optional<ClassRoom> classroom(Long id){return classes.findById(id);} public boolean teacher(Long id){return teachers.existsByUserId(id);}
}
